(function(){"use strict";app.factory("bodegaService",function(e){const t=e.get("mainService"),n="Inventario/Bodega/",o={get:function(e){return t.getData("get",n+"?json="+JSON.stringify(e),null,!0).then(e=>{if("0"===e.code)throw e;if("1"===e.code){let t=JSON.parse(e.payload)||[];return t.map(e=>({idBodega:e.idBodega,codEstab:e.codEstab,descripcion:e.descripcion,telefono:e.telefono,direccion:e.direccion,estado:e.estado,nombreComercial:e.nombreComercial,totalRecords:e.totalRecords}))}})},save:function(e){return t.getData("post",`${n}?json=${JSON.stringify(e)}`,null,!0)},update:function(e,o){return t.getData("put",`${n}${e}?json=${JSON.stringify(o)}`,null,!0)},delete:function(e){return t.getData("delete",n+e,null,!0)}};return o})})(window.angular);